package lesson

import (
	"net/http"
	"net/http/httptest"
	"testing"
)

func TestRequestInputs(t *testing.T) {
	request := httptest.NewRequest(http.MethodGet, "/users/42?verbose=true", nil)
	request.Header.Set("X-Request-ID", "abc")
	recorder := httptest.NewRecorder()
	NewHandler().ServeHTTP(recorder, request)
	if got := recorder.Body.String(); got != "id=42 verbose=true request=abc" {
		t.Fatal(got)
	}
}
```

