```go
package lesson

import (
	"encoding/json"
	"errors"
	"io"
	"net/http"
)

type createUser struct {
	Name string `json:"name"`
	Age  int    `json:"age"`
}

func CreateUser(w http.ResponseWriter, r *http.Request) {
	r.Body = http.MaxBytesReader(w, r.Body, 1024)
	decoder := json.NewDecoder(r.Body)
	decoder.DisallowUnknownFields()
	var input createUser
	if err := decoder.Decode(&input); err != nil {
		var tooLarge *http.MaxBytesError
		if errors.As(err, &tooLarge) {
			http.Error(w, "body too large", http.StatusRequestEntityTooLarge)
			return
		}
		http.Error(w, "invalid JSON", http.StatusBadRequest)
		return
	}
	if err := decoder.Decode(&struct{}{}); !errors.Is(err, io.EOF) {
		http.Error(w, "one JSON value required", http.StatusBadRequest)
		return
	}
	if input.Name == "" || input.Age < 0 {
		http.Error(w, "invalid user", http.StatusBadRequest)
		return
	}
	w.WriteHeader(http.StatusCreated)
}
```

**decode_test.go**

```go
package lesson

import (
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"
)

func TestCreateUser(t *testing.T) {
	for _, test := range []struct {
		body string
		want int
	}{
		{`{"name":"Ada","age":36}`, http.StatusCreated},
		{`{"name":"Ada"}{"name":"Lin"}`, http.StatusBadRequest},
		{`{"name":"","age":1}`, http.StatusBadRequest},
		{`{"name":"` + strings.Repeat("a", 1100) + `","age":1}`, http.StatusRequestEntityTooLarge},
	} {
		recorder := httptest.NewRecorder()
		CreateUser(recorder, httptest.NewRequest(http.MethodPost, "/users", strings.NewReader(test.body)))
		if recorder.Code != test.want {
			t.Fatalf("body=%s status=%d", test.body, recorder.Code)
		}
	}
}
```

**Run it**

```bash
go test -race ./...
go vet ./...
```

The second decode is intentional: only `io.EOF` proves that whitespace, rather than another JSON document, follows the accepted value.

